SELECT ?item ?itemLabel ?start ?end ?days WHERE {
  ?item p:P39 ?statement .
  ?statement ps:P39 wd:Q9134365 ;
             pq:P580 ?start .
  OPTIONAL { ?statement pq:P582 ?end . }
  BIND(COALESCE(?end, "2026-10-08T00:00:00Z"^^xsd:dateTime) AS ?endpoint)
  BIND((?endpoint - ?start) AS ?days)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?days)

